<script setup lang="ts">
import{computed,defineAsyncComponent,onMounted,ref}from"vue";import{InfoFilled,RefreshRight}from"@element-plus/icons-vue";import{fetchBlConsumption,type BlPayload}from"../api/blConsumption";import{useThemeStore}from"../stores/theme";
const Chart=defineAsyncComponent(()=>import("../components/ContentRankingChart.vue")),theme=useThemeStore(),data=ref<BlPayload|null>(null),periodEnd=ref(""),sort=ref("rank"),loading=ref(false),error=ref(""),drawer=ref(false),nf=new Intl.NumberFormat("zh-CN");const num=(v:number|null|undefined)=>v==null?"--":nf.format(v),pct=(v:number|null|undefined)=>v==null?"--":`${(v*100).toFixed(2)}%`;
async function load(){loading.value=true;error.value="";try{data.value=await fetchBlConsumption({period_end:periodEnd.value||undefined,sort:sort.value});if(!periodEnd.value&&data.value.summary)periodEnd.value=data.value.summary.period_end}catch(e){error.value="BL 内容消费加载失败。";console.error(e)}finally{loading.value=false}}
function changePeriod(){load()}function setSort(v:string){sort.value=v;load()}
const weekChange=computed(()=>{const periods=data.value?.periods??[],current=data.value?.summary;if(!current)return null;const index=periods.findIndex(x=>x.start===current.period_start&&x.end===current.period_end),previous=periods[index+1];return previous?"可切换上一周期核对":"--"}),option=computed(()=>({color:[theme.current.primary],grid:{left:130,right:30,top:12,bottom:24},tooltip:{trigger:"axis",axisPointer:{type:"shadow"}},xAxis:{type:"value"},yAxis:{type:"category",data:(data.value?.items??[]).slice(0,10).reverse().map(x=>x.title.length>10?x.title.slice(0,10)+"…":x.title)},series:[{type:"bar",barMaxWidth:18,data:(data.value?.items??[]).slice(0,10).reverse().map(x=>sort.value==="play_uv"?x.play_uv:x.play_vv)}]}));onMounted(load);
</script>
<template><main class="main-content page-stack"><header class="page-intro"><div><h2>BL 内容消费</h2><p>以题材标签中的精确标签“同性”识别 BL 内容。</p></div><button class="source-button" @click="drawer=true"><el-icon><InfoFilled/></el-icon>数据说明</button></header><section class="filter-bar ranking-filter"><label><span>统计周期</span><el-select v-model="periodEnd" @change="changePeriod"><el-option v-for="p in data?.periods" :key="p.start+'|'+p.end" :label="`${p.start} 至 ${p.end}`" :value="p.end"/></el-select></label><div class="ranking-tabs"><button :class="{active:sort==='play_vv'}" @click="setSort('play_vv')">播放VV</button><button :class="{active:sort==='play_uv'}" @click="setSort('play_uv')">播放UV</button></div><el-button type="primary" :loading="loading" @click="load"><el-icon><RefreshRight/></el-icon>更新视图</el-button><div class="freshness"><span class="status-dot"></span><div><b>真实内容数据</b><small>{{data?.meta.component??'--'}}</small></div></div></section><el-alert v-if="error" :title="error" type="error" show-icon :closable="false"/><section class="ranking-summary-grid bl-summary-grid"><article class="metric-item"><div class="metric-label"><span>BL 播放VV</span><small>内容播放次数</small></div><strong>{{num(data?.summary?.bl_play_vv)}}</strong></article><article class="metric-item"><div class="metric-label"><span>BL 内容播放UV合计</span><small>不做跨内容去重</small></div><strong>{{num(data?.summary?.bl_content_play_uv)}}</strong></article><article class="metric-item"><div class="metric-label"><span>BL 播放VV占比</span><small>同一内容口径</small></div><strong>{{pct(data?.summary?.bl_vv_share)}}</strong></article><article class="metric-item"><div class="metric-label"><span>BL 人均播放次数</span><small>VV ÷ 内容UV合计</small></div><strong>{{data?.summary?.bl_avg_play_count?.toFixed(2)??'--'}}</strong></article><article class="metric-item"><div class="metric-label"><span>周期对比</span><small>完整区间</small></div><strong class="metric-note-value">{{weekChange}}</strong></article></section><section class="panel"><div class="panel-head"><div><h2>{{sort==='play_uv'?'播放UV':'播放VV'}} Top10</h2><p>{{data?.summary?.period_start}} 至 {{data?.summary?.period_end}}</p></div></div><Chart v-if="data?.items.length" class="ranking-chart" :option="option"/></section><section class="panel ranking-detail-panel"><div class="panel-head"><div><h2>BL 内容播放榜</h2><p>真实 Top20 · {{data?.meta.rule}}</p></div><strong>{{data?.items.length??0}} 条</strong></div><div v-loading="loading" class="table-wrap"><table class="client-table ranking-table"><thead><tr><th>排名</th><th>内容名称</th><th>播放VV</th><th>播放UV</th><th>人均播放次数</th><th>剧种</th><th>内容类型</th><th>题材标签</th><th>产地</th></tr></thead><tbody><tr v-for="x in data?.items" :key="x.season_id"><td><span class="rank-badge">{{x.rank}}</span></td><td class="ranking-title"><strong>{{x.title}}</strong><small>ID {{x.season_id}}</small></td><td>{{num(x.play_vv)}}</td><td>{{num(x.play_uv)}}</td><td>{{x.avg_play_count?.toFixed(2)??'--'}}</td><td>{{x.genre??'--'}}</td><td>{{x.content_type??'--'}}</td><td class="genre-cell">{{x.topic_tags??'--'}}</td><td>{{x.producer_region??'--'}}</td></tr></tbody></table></div></section><el-drawer v-model="drawer" title="BL 内容消费来源与口径" size="440px"><div class="source-drawer"><section><span>数据源</span><strong>{{data?.meta.source??'--'}}</strong></section><section><span>接口</span><strong>{{data?.meta.component??'--'}}</strong></section><section><span>识别规则</span><strong>{{data?.meta.rule??'--'}}</strong></section><section><span>原始字段</span><div class="field-tags"><code v-for="f in data?.meta.original_fields" :key="f">{{f}}</code></div></section><p>{{data?.meta.limitation}}</p><p>因此“BL用户占全站播放用户比例”和“BL播放UV占全站比例”继续标记为待接入，不使用内容UV相加值替代。</p></div></el-drawer></main></template>
